<script dangerouslySetInnerHTML={{__html:"\r\n(function () {\r\n  var track   = document.getElementById('reviewsTrack');\r\n  var prevBtn = document.getElementById('reviewsPrev');\r\n  var nextBtn = document.getElementById('reviewsNext');\r\n  if (!track || !prevBtn || !nextBtn) return;\r\n\r\n  // Take over from CSS animation completely\r\n  track.style.animation = 'none';\r\n\r\n  var position   = 0;      // current translateX in px (0 to -halfWidth)\r\n  var paused     = false;\r\n  var resumeTimer = null;\r\n  var lastTs      = null;\r\n\r\n  function halfWidth()  { return track.scrollWidth / 2; }\r\n  function cardWidth()  { var c = track.querySelector('.review-card'); return c ? c.offsetWidth + 24 : 364; }\r\n\r\n  // RAF loop – moves at same speed as the original 60 s CSS animation\r\n  function loop(ts) {\r\n    if (lastTs !== null && !paused) {\r\n      var dt   = ts - lastTs;                          // ms since last frame\r\n      var half = halfWidth();\r\n      var spd  = half / (60 * 1000);                  // px per ms  (60 s full cycle)\r\n      position -= spd * dt;\r\n      if (position <= -half) position += half;         // seamless wrap\r\n      track.style.transform = 'translateX(' + position + 'px)';\r\n    }\r\n    lastTs = ts;\r\n    requestAnimationFrame(loop);\r\n  }\r\n\r\n  // Shift by one card and pause briefly\r\n  function shift(delta) {\r\n    var half = halfWidth();\r\n    position += delta;\r\n    if (position <= -half) position += half;\r\n    if (position > 0)      position -= half;\r\n    track.style.transform = 'translateX(' + position + 'px)';\r\n    paused = true;\r\n    clearTimeout(resumeTimer);\r\n    resumeTimer = setTimeout(function () { paused = false; }, 2500);\r\n  }\r\n\r\n  prevBtn.addEventListener('click', function () { shift( cardWidth()); });\r\n  nextBtn.addEventListener('click', function () { shift(-cardWidth()); });\r\n\r\n  // Pause on hover\r\n  var wrapper = document.querySelector('.reviews-carousel-wrapper');\r\n  if (wrapper) {\r\n    wrapper.addEventListener('mouseenter', function () { paused = true;  });\r\n    wrapper.addEventListener('mouseleave', function () { paused = false; });\r\n  }\r\n\r\n  requestAnimationFrame(loop);\r\n})();\r\n"}} />

  

  
